import {STUDY_PALETTES,STUDY_FINISHES,studioGroup} from './studio-study.js?v=42.0.0';
export function studioStudyHTML(s,st,draft,{esc}){
 const palette=STUDY_PALETTES.find(p=>p.id===draft.palette),finish=STUDY_FINISHES.find(f=>f.id===draft.finish),group=studioGroup(st),saved=(s.materialStudies||[]).find(n=>n.store===st.id),same=saved?.palette===draft.palette&&saved?.finish===draft.finish;
 const materials={textile:['Woven swatch','Folded sample','Seam study'],light:['Light dome','Inset tile','Reflector'],workshop:['Room panel','Joinery block','Surface tile']}[group];
 return `<div class="modal-body material-study"><span class="eyebrow">MALLSIDE MATERIAL STUDIO</span><p>Try a palette and surface finish on this original ${group==='textile'?'textile':group==='light'?'light-and-color':'workshop'} study. ${st.count?'Compare these creative samples separately from the verified collection.':'The shop’s photographed catalog is still being researched.'} These samples are creative props, not merchandise.</p><div class="study-preview" data-finish="${draft.finish}" role="img" aria-label="${esc(palette.name+' · '+finish.name+' samples: '+palette.labels.join(', '))}">${palette.colors.map((color,i)=>`<div class="study-sample" style="--sample:${color}"><i aria-hidden="true"></i><strong>${esc(palette.labels[i])}</strong><small>${materials[i]}</small></div>`).join('')}</div><fieldset><legend>1. Choose a palette</legend><div class="study-choices">${STUDY_PALETTES.map(p=>`<button class="button secondary" data-action="studio-palette" data-id="${p.id}" aria-pressed="${draft.palette===p.id}"><span class="study-chips" aria-hidden="true">${p.colors.map(c=>`<i style="background:${c}"></i>`).join('')}</span>${esc(p.name)}</button>`).join('')}</div></fieldset><fieldset><legend>2. Compare the finish</legend><div class="study-choices">${STUDY_FINISHES.map(f=>`<button class="button secondary" data-action="studio-finish" data-id="${f.id}" aria-pressed="${draft.finish===f.id}"><strong>${f.name}</strong><small>${f.description}</small></button>`).join('')}</div></fieldset><p class="study-status" role="status">${same?'Saved here · day '+saved.day+'. Your study will be on the desk when you return.':'Preview: '+esc(palette.name)+' · '+finish.name+'. Save to keep it at this shop.'}</p><p class="hint">Free creative study · saving spends no money or game time, reserves no stock and awards no XP. Close without saving to discard the preview.</p><button class="button secondary wide" data-action="shop-plan-open" data-id="${esc(st.id)}">Plan verified finds at their actual shops</button><button class="button secondary wide" data-action="back-store">Back to the shop guide</button></div>`;
}
